inline SpleenNativeFont spleen_native_font(SpleenNativeSize size) {
    switch (size) {
        case SpleenNativeSize::S5x8:
            return {5, 8, 3, &kSpleen5x8Glyphs[0][0][0]};
        case SpleenNativeSize::S6x12:
            return {6, 12, 3, &kSpleen6x12Glyphs[0][0][0]};
        case SpleenNativeSize::S8x16:
            return {8, 16, 4, &kSpleen8x16Glyphs[0][0][0]};
        case SpleenNativeSize::S12x24:
            return {12, 24, 6, &kSpleen12x24Glyphs[0][0][0]};
        case SpleenNativeSize::S16x32:
            return {16, 32, 8, &kSpleen16x32Glyphs[0][0][0]};
        case SpleenNativeSize::S32x64:
            return {32, 64, 16, &kSpleen32x64Glyphs[0][0][0]};
        default:
            return {12, 24, 6, &kSpleen12x24Glyphs[0][0][0]};
    }
}

inline const uint8_t* spleen_native_glyph(const SpleenNativeFont& font, char ch) {
    const unsigned code = static_cast<unsigned char>(ch);
    const unsigned index = (code < kSpleenNativeFirstChar || code > kSpleenNativeLastChar)
                               ? 0u
                               : code - kSpleenNativeFirstChar;
    return font.glyphs + index * font.height * font.packed_width;
}

